let tousLesProduits = [];

// 1. Merge results from every page
for (const item of $input.all()) {
  let texteIA = "";

  if (Array.isArray(item.json) && item.json[0] && item.json[0].content) {
    texteIA = item.json[0].content[0].text;
  } else if (item.json.content && Array.isArray(item.json.content)) {
    texteIA = item.json.content[0].text;
  } else if (item.json.message && item.json.message.content) {
    texteIA = typeof item.json.message.content === 'string' ? item.json.message.content : item.json.message.content[0].text;
  } else if (item.json.text) {
    texteIA = item.json.text;
  }

  if (!texteIA) continue;

  texteIA = texteIA.replace(/```json/g, "").replace(/```/g, "").trim();

  try {
    let listeProduits = JSON.parse(texteIA);
    if (Array.isArray(listeProduits) && listeProduits.length > 0) {
      tousLesProduits = tousLesProduits.concat(listeProduits);
    }
  } catch (error) {
    continue;
  }
}

// 2. Compute discounts cleanly with proper decimal handling
tousLesProduits.forEach(produit => {
  // Make sure prices are numeric (replace a comma with a dot if the AI slipped up)
  let ancien = parseFloat(String(produit.ancien_prix).replace(',', '.'));
  let nouveau = parseFloat(String(produit.nouveau_prix).replace(',', '.'));

  if (!isNaN(ancien) && !isNaN(nouveau) && ancien > 0) {
    // Savings rounded to 2 decimal places (e.g. 98.99)
    produit.economie_euros = parseFloat((ancien - nouveau).toFixed(2));
    // Discount percentage
    produit.pourcentage_reduction = Math.round((produit.economie_euros / ancien) * 100);
  } else {
    produit.economie_euros = 0;
    produit.pourcentage_reduction = 0;
  }

  // Write the cleaned values back to the object
  produit.ancien_prix = ancien;
  produit.nouveau_prix = nouveau;
});

// 3. Sort from largest discount percentage to smallest
tousLesProduits.sort((a, b) => b.pourcentage_reduction - a.pourcentage_reduction);

// 4. Return the final result
return [{
  json: {
    catalogue_complet: tousLesProduits,
    total_produits_trouves: tousLesProduits.length
  }
}];

